use super::tables::CHILE_ABORIGINAL_PEOPLE_DAY;
use super::{easter_monday, is_weekend, Day};
#[allow(unused_imports)]
use crate::time::Weekday::{Friday, Monday, Saturday, Sunday, Thursday, Tuesday, Wednesday};

fn is_aboriginal_people_day(d: i32, m: i32, y: i32) -> bool {
    m == 6 && y >= 2021 && d == CHILE_ABORIGINAL_PEOPLE_DAY[(y - 2021) as usize]
}

pub(in crate::time::calendar) fn argentina_merval(x: &Day) -> bool {
    let (d, m, w, dd, y) = (x.d, x.m, x.w, x.dd, x.y);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            // Holy Thursday
            || (dd == em-4)
            // Good Friday
            || (dd == em-3)
            // Labour Day
            || (d == 1 && m == 5)
            // May Revolution
            || (d == 25 && m == 5)
            // Death of General Manuel Belgrano
            || (d >= 15 && d <= 21 && w == Monday && m == 6)
            // Independence Day
            || (d == 9 && m == 7)
            // Death of General José de San Martín
            || (d >= 15 && d <= 21 && w == Monday && m == 8)
            // Columbus Day
            || ((d == 10 || d == 11 || d == 12 || d == 15 || d == 16)
                && w == Monday && m == 10)
            // Immaculate Conception
            || (d == 8 && m == 12)
            // Christmas Eve
            || (d == 24 && m == 12)
            // New Year's Eve
            || ((d == 31 || (d == 30 && w == Friday)) && m == 12)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn brazil_settlement(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            // Tiradentes Day
            || (d == 21 && m == 4)
            // Labor Day
            || (d == 1 && m == 5)
            // Independence Day
            || (d == 7 && m == 9)
            // Nossa Sra. Aparecida Day
            || (d == 12 && m == 10)
            // All Souls Day
            || (d == 2 && m == 11)
            // Republic Day
            || (d == 15 && m == 11)
            // Black Awareness Day
            || (d == 20 && m == 11 && y >= 2024)
            // Christmas
            || (d == 25 && m == 12)
            // Passion of Christ
            || (dd == em-3)
            // Carnival
            || (dd == em-49 || dd == em-48)
            // Corpus Christi
            || (dd == em+59)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn brazil_exchange(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            // Sao Paulo City Day
            || (d == 25 && m == 1 && y < 2022)
            // Tiradentes Day
            || (d == 21 && m == 4)
            // Labor Day
            || (d == 1 && m == 5)
            // Revolution Day
            || (d == 9 && m == 7 && y < 2022)
            // Independence Day
            || (d == 7 && m == 9)
            // Nossa Sra. Aparecida Day
            || (d == 12 && m == 10)
            // All Souls Day
            || (d == 2 && m == 11)
            // Republic Day
            || (d == 15 && m == 11)
            // Black Consciousness Day
            || (d == 20 && m == 11 && y >= 2007 && y != 2022 && y != 2023)
            // Christmas Eve
            || (d == 24 && m == 12)
            // Christmas
            || (d == 25 && m == 12)
            // Passion of Christ
            || (dd == em-3)
            // Carnival
            || (dd == em-49 || dd == em-48)
            // Corpus Christi
            || (dd == em+59)
            // last business day of the year
            || (m == 12 && (d == 31 || (d >= 29 && w == Friday)))
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn canada_settlement(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day (possibly moved to Monday)
            || ((d == 1 || ((d == 2 || d == 3) && w == Monday)) && m == 1)
            // Family Day (third Monday in February, since 2008)
            || ((d >= 15 && d <= 21) && w == Monday && m == 2
                && y >= 2008)
            // Good Friday
            || (dd == em-3)
            // The Monday on or preceding 24 May (Victoria Day)
            || (d > 17 && d <= 24 && w == Monday && m == 5)
            // July 1st, possibly moved to Monday (Canada Day)
            || ((d == 1 || ((d == 2 || d == 3) && w == Monday)) && m==7)
            // first Monday of August (Provincial Holiday)
            || (d <= 7 && w == Monday && m == 8)
            // first Monday of September (Labor Day)
            || (d <= 7 && w == Monday && m == 9)
            // September 30th, possibly moved to Monday
            // (National Day for Truth and Reconciliation, since 2021)
            || (((d == 30 && m == 9) || (d <= 2 && m == 10 && w == Monday)) && y >= 2021)
            // second Monday of October (Thanksgiving Day)
            || (d > 7 && d <= 14 && w == Monday && m == 10)
            // November 11th (possibly moved to Monday)
            || ((d == 11 || ((d == 12 || d == 13) && w == Monday))
                && m == 11)
            // Christmas (possibly moved to Monday or Tuesday)
            || ((d == 25 || (d == 27 && (w == Monday || w == Tuesday)))
                && m == 12)
            // Boxing Day (possibly moved to Monday or Tuesday)
            || ((d == 26 || (d == 28 && (w == Monday || w == Tuesday)))
                && m == 12)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn canada_tsx(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day (possibly moved to Monday)
            || ((d == 1 || ((d == 2 || d == 3) && w == Monday)) && m == 1)
            // Family Day (third Monday in February, since 2008)
            || ((d >= 15 && d <= 21) && w == Monday && m == 2
                && y >= 2008)
            // Good Friday
            || (dd == em-3)
            // The Monday on or preceding 24 May (Victoria Day)
            || (d > 17 && d <= 24 && w == Monday && m == 5)
            // July 1st, possibly moved to Monday (Canada Day)
            || ((d == 1 || ((d == 2 || d == 3) && w == Monday)) && m==7)
            // first Monday of August (Provincial Holiday)
            || (d <= 7 && w == Monday && m == 8)
            // first Monday of September (Labor Day)
            || (d <= 7 && w == Monday && m == 9)
            // second Monday of October (Thanksgiving Day)
            || (d > 7 && d <= 14 && w == Monday && m == 10)
            // Christmas (possibly moved to Monday or Tuesday)
            || ((d == 25 || (d == 27 && (w == Monday || w == Tuesday)))
                && m == 12)
            // Boxing Day (possibly moved to Monday or Tuesday)
            || ((d == 26 || (d == 28 && (w == Monday || w == Tuesday)))
                && m == 12)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn chile_sse(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            || (d == 2 && m == 1 && w == Monday && y > 2016)
            // Papal visit in 2018
            || (d == 16 && m == 1 && y == 2018)
            // Good Friday
            || (dd == em-3)
            // Easter Saturday
            || (dd == em-2)
            // Census Day in 2017
            || (d == 19 && m == 4 && y == 2017)
            // Labour Day
            || (d == 1 && m == 5)
            // Navy Day
            || (d == 21 && m == 5)
            // Day of Aboriginal People
            || is_aboriginal_people_day(d, m, y)
            // St. Peter and St. Paul
            || (d >= 26 && d <= 29 && m == 6 && w == Monday)
            || (d == 2 && m == 7 && w == Monday)
            // Our Lady of Mount Carmel
            || (d == 16 && m == 7)
            // Assumption Day
            || (d == 15 && m == 8)
            // Independence Day
            || (d == 16 && m == 9 && y == 2022)
            || (d == 17 && m == 9 && ((w == Monday && y >= 2007) || (w == Friday && y > 2016)))
            || (d == 18 && m == 9)
            // Army Day
            || (d == 19 && m == 9)
            || (d == 20 && m == 9 && w == Friday && y >= 2007)
            // Discovery of Two Worlds
            || (d >= 9 && d <= 12 && m == 10 && w == Monday)
            || (d == 15 && m == 10 && w == Monday)
            // Reformation Day
            || (((d == 27 && m == 10 && w == Friday)
                 || (d == 31 && m == 10 && w != Tuesday && w != Wednesday)
                 || (d == 2 && m == 11 && w == Friday)) && y >= 2008)
            // All Saints' Day
            || (d == 1 && m == 11)
            // Immaculate Conception
            || (d == 8 && m == 12)
            // Christmas Day
            || (d == 25 && m == 12)
            // New Year's Eve 
            || (d == 31 && m == 12)
    {
        return false;
    }
    true
}

pub(in crate::time::calendar) fn mexico_bmv(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            // Constitution Day
            || (y <= 2005 && d == 5 && m == 2)
            || (y >= 2006 && d <= 7 && w == Monday && m == 2)
            // Birthday of Benito Juarez
            || (y <= 2005 && d == 21 && m == 3)
            || (y >= 2006 && (d >= 15 && d <= 21) && w == Monday && m == 3)
            // Holy Thursday
            || (dd == em-4)
            // Good Friday
            || (dd == em-3)
            // Labour Day
            || (d == 1 && m == 5)
            // National Day
            || (d == 16 && m == 9)
            // Inauguration Day
            || (d == 1 && m == 10 && y >= 2024 && (y - 2024) % 6 == 0)
            // All Souls Day
            || (d == 2 && m == 11)
            // Revolution Day
            || (y <= 2005 && d == 20 && m == 11)
            || (y >= 2006 && (d >= 15 && d <= 21) && w == Monday && m == 11)
            // Our Lady of Guadalupe
            || (d == 12 && m == 12)
            // Christmas
            || (d == 25 && m == 12)
    {
        return false;
    }

    true
}
